<?php
declare(strict_types=1);

const DATA_FILE = __DIR__ . '/processes.json';
const MAX_BODY = 4194304;
const MAX_PROCESSES = 500;
const MAX_STEPS = 150;
const MAX_VARIABLES = 150;
const MAX_FIELDS = 250;
$ENABLE_LEGACY_IMPORT = true;

$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';
session_set_cookie_params(['httponly'=>true,'secure'=>$https,'samesite'=>'Strict','path'=>'/']);
session_start();
if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
header('Content-Type: text/html; charset=UTF-8');
header("Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; base-uri 'self'; form-action 'self'");
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: no-referrer');
header('X-Frame-Options: SAMEORIGIN');

function esc(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function txt(mixed $v,int $max=5000):string{$v=trim(is_scalar($v)?(string)$v:'');return function_exists('mb_substr')?mb_substr($v,0,$max,'UTF-8'):substr($v,0,$max);}
function uid(string $p):string{return $p.'-'.bin2hex(random_bytes(8));}
function vals(mixed $v):array{if(is_string($v))$v=preg_split('/\R/u',$v)?:[];if(!is_array($v))return[];$o=[];foreach(array_slice($v,0,300) as $x){$x=txt($x,300);if($x!==''&&!in_array($x,$o,true))$o[]=$x;}return$o;}
function blankData():array{return['schemaVersion'=>3,'configuration'=>['fields'=>[],'linkTypes'=>[]],'processes'=>[]];}
function fieldType(mixed $v):string{$v=txt($v,30);return in_array($v,['text','select','number'],true)?$v:'text';}
function variableType(mixed $v):string{$v=txt($v,30);return in_array($v,['text','select','number','random'],true)?$v:'text';}
function cleanField(array $f,int $i=0):array{return['id'=>txt($f['id']??'',100)?:uid('field'),'key'=>txt($f['key']??$f['name']??'',120),'label'=>txt($f['label']??$f['name']??$f['key']??'',160),'type'=>fieldType($f['type']??'text'),'values'=>vals($f['values']??$f['options']??[]),'defaultValue'=>txt($f['defaultValue']??$f['default']??'',5000),'required'=>(bool)($f['required']??false)];}
function cleanVariable(array $v):array{return['id'=>txt($v['id']??'',100)?:uid('variable'),'name'=>txt($v['name']??'',160),'type'=>variableType($v['type']??'text'),'values'=>vals($v['values']??[]),'prefill'=>txt($v['prefill']??$v['default']??'',5000),'minimum'=>isset($v['minimum'])&&$v['minimum']!==''?(float)$v['minimum']:null,'maximum'=>isset($v['maximum'])&&$v['maximum']!==''?(float)$v['maximum']:null,'hidden'=>(bool)($v['hidden']??false),'marked'=>(bool)($v['marked']??false)];}
function cleanStep(array $st):array{
  $fields=[];foreach(array_slice(is_array($st['fields']??null)?$st['fields']:[],0,MAX_FIELDS) as $f)if(is_array($f)){$key=txt($f['key']??$f['field']??'',120);if($key!=='')$fields[]=['id'=>txt($f['id']??'',100)?:uid('step-field'),'key'=>$key,'value'=>txt($f['value']??'',5000),'enabled'=>(bool)($f['enabled']??true)];}
  $links=[];foreach(array_slice(is_array($st['links']??null)?$st['links']:[],0,30) as $l)if(is_array($l))$links[]=['id'=>txt($l['id']??'',100)?:uid('link'),'object'=>txt($l['object']??'Ticket',60),'type'=>txt($l['type']??'Normal',100),'target'=>txt($l['target']??'',5000)];
  $meta=is_array($st['meta']??null)?$st['meta']:[];$tasks=[];foreach(array_slice(is_array($meta['tasks']??null)?$meta['tasks']:[],0,100) as $t)if(is_array($t))$tasks[]=['kind'=>txt($t['kind']??'Klicken',40),'instruction'=>txt($t['instruction']??'',5000),'target'=>txt($t['target']??'',5000)];
  $condition=is_array($meta['condition']??null)?$meta['condition']:[];
  return['id'=>txt($st['id']??'',100)?:uid('step'),'action'=>txt($st['action']??'note',50),'subject'=>txt($st['subject']??$st['title']??'',5000),'body'=>txt($st['body']??$st['text']??'',30000),'fields'=>$fields,'links'=>$links,'meta'=>['system'=>txt($meta['system']??'',5000),'url'=>txt($meta['url']??'',5000),'address'=>txt($meta['address']??'',5000),'tasks'=>$tasks,'condition'=>['variable'=>txt($condition['variable']??'',160),'operator'=>txt($condition['operator']??'always',40),'value'=>txt($condition['value']??'',5000)]]];
}
function cleanProcess(array $p):array{
 $variables=[];foreach(array_slice(is_array($p['variables']??null)?$p['variables']:[],0,MAX_VARIABLES) as $v)if(is_array($v)){ $v=cleanVariable($v);if($v['name']!=='')$variables[]=$v;}
 $steps=[];foreach(array_slice(is_array($p['steps']??null)?$p['steps']:[],0,MAX_STEPS) as $s)if(is_array($s))$steps[]=cleanStep($s);
 if(!$steps)$steps[]=['id'=>uid('step'),'action'=>'ticket-create','subject'=>'','body'=>'','fields'=>[],'links'=>[],'meta'=>['system'=>'','url'=>'','address'=>'','tasks'=>[],'condition'=>['variable'=>'','operator'=>'always','value'=>'']]];
 return['id'=>txt($p['id']??'',100)?:uid('process'),'name'=>txt($p['name']??'Unbenannter Prozess',160),'description'=>txt($p['description']??'',1000),'yamlName'=>txt($p['yamlName']??'',200),'published'=>(bool)($p['published']??true),'customerMarks'=>is_array($p['customerMarks']??null)?$p['customerMarks']:[],'variables'=>$variables,'steps'=>$steps,'updatedAt'=>txt($p['updatedAt']??'',50)?:date(DATE_ATOM)];
}
function normalize(array $raw):array{
 $cfg=is_array($raw['configuration']??$raw['config']??null)?($raw['configuration']??$raw['config']):[];$fieldsRaw=$cfg['fields']??$cfg['ticketFields']??[];
 if(!is_array($fieldsRaw))$fieldsRaw=[];$fields=[];foreach(array_slice($fieldsRaw,0,MAX_FIELDS) as $i=>$f)if(is_array($f)){ $f=cleanField($f,$i);if($f['key']!=='')$fields[]=$f;}
 $list=$raw['processes']??$raw['masks']??[];if(!is_array($list))$list=[];$processes=[];foreach(array_slice($list,0,MAX_PROCESSES) as $p)if(is_array($p))$processes[]=cleanProcess($p);
 return['schemaVersion'=>3,'configuration'=>['fields'=>$fields,'linkTypes'=>vals($cfg['linkTypes']??$cfg['links']??[])],'processes'=>$processes];
}
function legacyNormalize(array $raw):array{$n=normalize($raw);if(!$n['configuration']['fields']){$seen=[];foreach($n['processes'] as $p)foreach($p['steps'] as $si=>$st)foreach($st['fields'] as $f){$k=$f['key'];if(!isset($seen[$k]))$seen[$k]=['id'=>uid('field'),'key'=>$k,'label'=>$k,'type'=>'text','values'=>[],'defaultValue'=>'','required'=>$si===0];}$n['configuration']['fields']=array_values($seen);}return$n;}
function loadData():array{if(!is_file(DATA_FILE))return blankData();$raw=file_get_contents(DATA_FILE);if($raw===false)throw new RuntimeException('Daten konnten nicht gelesen werden.');$json=json_decode($raw,true,512,JSON_THROW_ON_ERROR);return normalize(is_array($json)?$json:[]);}
function saveData(array $data):void{$tmp=DATA_FILE.'.tmp';$json=json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n";if(file_put_contents($tmp,$json,LOCK_EX)===false)throw new RuntimeException('Daten konnten nicht gespeichert werden.');if(!rename($tmp,DATA_FILE)){@unlink($tmp);throw new RuntimeException('Daten konnten nicht übernommen werden.');}}
function actionLabel(string $a):string{return['ticket-create'=>'Ticket erstellen','ticket-edit'=>'Ticketfeld ändern','title-edit'=>'Titel ändern','note'=>'Hinweis / Text','external-task'=>'Externes System','phone-in'=>'Telefon eingehend','phone-out'=>'Telefon ausgehend','email-in'=>'E-Mail eingehend','email-out'=>'E-Mail ausgehend','link'=>'Verknüpfen','close'=>'Ticket schließen'][$a]??'Schritt';}

$error='';try{$data=loadData();}catch(Throwable $e){$data=blankData();$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if((int)($_SERVER['CONTENT_LENGTH']??0)>MAX_BODY)throw new RuntimeException('Anfrage ist zu groß.');$payload=json_decode(file_get_contents('php://input')?:'',true,512,JSON_THROW_ON_ERROR);if(!hash_equals($_SESSION['csrf'],(string)($payload['csrf']??'')))throw new RuntimeException('Sitzung abgelaufen.');$op=txt($payload['op']??'',40);
  if($op==='save-process'){$process=cleanProcess(is_array($payload['process']??null)?$payload['process']:[]);if($process['name']==='')throw new RuntimeException('Prozessname fehlt.');$process['updatedAt']=date(DATE_ATOM);$found=false;foreach($data['processes'] as $i=>$old)if($old['id']===$process['id']){$data['processes'][$i]=$process;$found=true;break;}if(!$found){if(count($data['processes'])>=MAX_PROCESSES)throw new RuntimeException('Zu viele Prozesse.');$data['processes'][]=$process;}saveData($data);echo json_encode(['ok'=>true,'id'=>$process['id']]);exit;}
  if($op==='delete-process'){$id=txt($payload['id']??'',100);$data['processes']=array_values(array_filter($data['processes'],fn($p)=>$p['id']!==$id));saveData($data);echo json_encode(['ok'=>true]);exit;}
  if($op==='save-config'){$cfg=is_array($payload['configuration']??null)?$payload['configuration']:[];$fields=[];foreach(array_slice(is_array($cfg['fields']??null)?$cfg['fields']:[],0,MAX_FIELDS) as $i=>$f)if(is_array($f)){ $f=cleanField($f,$i);if($f['key']!=='')$fields[]=$f;}$data['configuration']=['fields'=>$fields,'linkTypes'=>vals($cfg['linkTypes']??[])];saveData($data);echo json_encode(['ok'=>true]);exit;}
  if($op==='import-current'){$incoming=is_array($payload['data']??null)?$payload['data']:[];if((int)($incoming['schemaVersion']??0)!==3)throw new RuntimeException('Die Datei ist kein Export dieses Systems.');$data=normalize($incoming);saveData($data);echo json_encode(['ok'=>true,'count'=>count($data['processes'])]);exit;}
  if($op==='import-legacy'){if(!$ENABLE_LEGACY_IMPORT)throw new RuntimeException('Altimport ist deaktiviert.');$incoming=is_array($payload['data']??null)?$payload['data']:[];$legacy=legacyNormalize($incoming);$ids=array_column($data['processes'],'id');foreach($legacy['processes'] as &$p)if(in_array($p['id'],$ids,true))$p['id']=uid('process');unset($p);$data['processes']=array_merge($data['processes'],$legacy['processes']);if(!$data['configuration']['fields']&&$legacy['configuration']['fields'])$data['configuration']=$legacy['configuration'];saveData($data);echo json_encode(['ok'=>true,'count'=>count($legacy['processes'])]);exit;}
  throw new RuntimeException('Unbekannte Aktion.');
 }catch(Throwable $e){http_response_code(400);header('Content-Type: application/json; charset=UTF-8');echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);exit;}
}
$page=txt($_GET['page']??'library',30);$id=txt($_GET['id']??'',100);$current=null;foreach($data['processes'] as $p)if($p['id']===$id)$current=$p;
?>
