Kundennummer: $§Kundennummer$§</pre></div></div></div></div>
<script>
const CSRF=<?=json_encode($_SESSION['csrf'])?>,CONFIG=<?=json_encode($data['configuration'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,PROCESSES=<?=json_encode($data['processes'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,PAGE=<?=json_encode($page)?>,CURRENT=<?=json_encode($current,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>Array.from(r.querySelectorAll(q));
document.addEventListener('click',e=>{if(!e.target.closest('.context'))closeContextMenus()});
const darkMedia=matchMedia('(prefers-color-scheme: dark)');const applyTheme=()=>document.documentElement.dataset.theme=darkMedia.matches?'dark':'light';applyTheme();darkMedia.addEventListener?.('change',applyTheme);document.addEventListener('DOMContentLoaded',()=>{const burger=$('#burger'),menu=$('#main-menu');if(burger&&menu){burger.onclick=()=>{const open=menu.classList.toggle('open');burger.setAttribute('aria-expanded',String(open))};document.addEventListener('click',e=>{if(!e.target.closest('.top')){menu.classList.remove('open');burger.setAttribute('aria-expanded','false')}})}});
function node(tag,attrs={},text=''){const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(k==='class')n.className=v;else if(k==='checked')n.checked=!!v;else if(k==='value')n.value=v??'';else if(k==='disabled')n.disabled=!!v;else if(k==='readonly')n.readOnly=!!v;else n.setAttribute(k,String(v))}if(text!=='')n.textContent=text;return n}
function notice(text,bad=false){const n=$('#status');n.textContent=text;n.style.background=bad?'#8b2525':'#222';n.classList.remove('hidden');setTimeout(()=>n.classList.add('hidden'),3200)}
async function api(payload){const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,csrf:CSRF})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Fehler');return j}
function openModal(id){$('#'+id).classList.remove('hidden')}function closeModal(id){$('#'+id).classList.add('hidden')}$$('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));
function labeled(text,input,cls='c12'){const d=node('div',{class:cls}),l=node('label',{},text);l.append(input);d.append(l);return d}
function select(options,value){const s=node('select');options.forEach(o=>s.append(node('option',{value:o},o)));s.value=value??options[0]??'';return s}
function fieldDef(key){return CONFIG.fields.find(f=>f.key===key)||{key,label:key,type:'text',values:[]}}
function blankStep(action){return{id:'step-'+crypto.randomUUID(),action,subject:'',body:'',fields:[],links:[],meta:{system:'',url:'',address:'',tasks:[],condition:{variable:'',operator:'always',value:''}}}}
const LABELS={'ticket-create':'Ticket erstellen','ticket-edit':'Ticketfeld ändern','title-edit':'Titel ändern','note':'Hinweis / Text','external-task':'Externes System','phone-in':'Telefon eingehend','phone-out':'Telefon ausgehend','email-in':'E-Mail eingehend','email-out':'E-Mail ausgehend','link':'Verknüpfen','close':'Ticket schließen'};
function variableNames(text){const out=[],rx=/\$\$([\s\S]{1,160}?)\$\$/g;let m;while((m=rx.exec(text||''))){const n=m[1].trim();if(n&&!out.includes(n))out.push(n)}return out}
function customerNames(text){const out=[],rx=/\$§([\s\S]{1,500}?)\$§/g;let m;while((m=rx.exec(text||''))){const n=m[1].trim();if(n&&!out.includes(n))out.push(n)}return out}
function scanVariables(process){const names=new Set();process.steps.forEach(s=>[s.subject,s.body,...s.fields.map(f=>f.value),...s.links.map(l=>l.target),s.meta.system,s.meta.address,...(s.meta.tasks||[]).flatMap(t=>[t.instruction,t.target])].forEach(t=>variableNames(t).forEach(n=>names.add(n))));names.forEach(n=>{if(!process.variables.some(v=>v.name===n))process.variables.push({id:'variable-'+crypto.randomUUID(),name:n,type:'text',values:[],prefill:'',minimum:null,maximum:null,hidden:false,marked:false})})}
function variableIsUsed(name){let used=false;process.steps.forEach(s=>[s.subject,s.body,...s.fields.map(f=>f.value),...s.links.map(l=>l.target),s.meta.system,s.meta.address,...(s.meta.tasks||[]).flatMap(t=>[t.instruction,t.target])].forEach(t=>{if(variableNames(t).includes(name))used=true}));return used}
function blankVariable(){return{id:'variable-'+crypto.randomUUID(),name:'',type:'text',values:[],prefill:'',minimum:null,maximum:null,hidden:false,marked:false}}
function openVariableManager(){scanVariables(process);const body=$('#edit-body'),list=node('div',{class:'variable-manager-list'});$('#edit-title').textContent='Variablen';function draw(){list.replaceChildren();process.variables.forEach((v,i)=>{const row=node('div',{class:'variable-manager-row'}),name=node('input',{type:'text',value:v.name}),type=select(['text','select','number','random'],v.type),used=node('span',{class:'variable-use '+(variableIsUsed(v.name)?'used':'unused')},variableIsUsed(v.name)?'im Text':'unabhängig'),up=node('button',{type:'button',disabled:i===0,title:'Nach oben'},'↑'),down=node('button',{type:'button',disabled:i===process.variables.length-1,title:'Nach unten'},'↓'),settings=node('button',{type:'button',title:'Einstellungen'},'Bearbeiten'),del=node('button',{type:'button',class:'danger',title:'Löschen'},'×');name.oninput=()=>v.name=name.value.trim();type.onchange=()=>v.type=type.value;up.onclick=()=>{if(i<1)return;[process.variables[i-1],process.variables[i]]=[process.variables[i],process.variables[i-1]];draw()};down.onclick=()=>{if(i>=process.variables.length-1)return;[process.variables[i+1],process.variables[i]]=[process.variables[i],process.variables[i+1]];draw()};settings.onclick=()=>editVariable(v.name,openVariableManager);del.onclick=()=>{process.variables.splice(i,1);draw()};row.append(node('span',{class:'variable-order'},String(i+1)),name,type,used,up,down,settings,del);list.append(row)})}draw();const add=node('button',{type:'button'},'Variable hinzufügen');add.onclick=()=>{process.variables.push(blankVariable());draw()};body.replaceChildren(list,add);$('#edit-apply').onclick=()=>{const names=new Set();for(const v of process.variables){v.name=v.name.trim();if(!v.name)return notice('Variablenname fehlt.',true);if(names.has(v.name))return notice('Variablennamen müssen eindeutig sein.',true);names.add(v.name)}closeModal('edit-modal')};openModal('edit-modal')}
function tokenPreview(container,input,onchange){container.replaceChildren();const src=input.value,rx=/(\$\$[\s\S]+?\$\$|\$§[\s\S]+?\$§)/g;let p=0,m,found=false;while((m=rx.exec(src))){found=true;container.append(document.createTextNode(src.slice(p,m.index)));const t=m[0];if(t.startsWith('$$')){const name=t.slice(2,-2).trim(),b=node('button',{type:'button',class:'token var-token',title:'Variable bearbeiten'},t);b.onclick=()=>editVariable(name);container.append(b)}else{const raw=t.slice(2,-2).trim(),b=node('button',{type:'button',class:'token customer-token'},t);b.onclick=()=>editCustomer(raw,input,onchange);container.append(b)}p=rx.lastIndex}container.append(document.createTextNode(src.slice(p)));container.classList.toggle('hidden',!found)}
function closeContextMenus(){document.querySelectorAll('.context').forEach(n=>n.remove())}
function editorPlainText(editor){let out='';editor.childNodes.forEach(child=>{if(child.nodeType===Node.TEXT_NODE)out+=child.nodeValue||'';else if(child.nodeName==='BR')out+='\n';else if(child.classList?.contains('editor-token'))out+=child.dataset.raw||child.textContent;else out+=child.textContent||''});return out}
function insertIntoField(input,before,after=before,placeholder='Text'){if(input.isContentEditable){input.focus();const selection=getSelection(),range=selection&&selection.rangeCount?selection.getRangeAt(0):null,text=selection&&!selection.isCollapsed?selection.toString():placeholder;if(range&&input.contains(range.commonAncestorContainer)){range.deleteContents();const value=before+text+after,nodeText=document.createTextNode(value);range.insertNode(nodeText);range.setStartAfter(nodeText);range.collapse(true);selection.removeAllRanges();selection.addRange(range)}else input.append(document.createTextNode(before+text+after));input.dispatchEvent(new Event('input',{bubbles:true}));return}const start=input.selectionStart??input.value.length,end=input.selectionEnd??start,selected=input.value.slice(start,end)||placeholder;input.setRangeText(before+selected+after,start,end,'end');input.dispatchEvent(new Event('input'));input.focus()}
function selectedText(input,fallback='Text'){if(input.isContentEditable){const selection=getSelection();return selection&&!selection.isCollapsed&&input.contains(selection.anchorNode)?selection.toString():fallback}return input.value.slice(input.selectionStart??0,input.selectionEnd??0)||fallback}
function insertVariableTool(input){const body=$('#edit-body'),name=node('input',{type:'text'}),existing=select(['',...(process?.variables||[]).map(v=>v.name)],'');$('#edit-title').textContent='Variable einfügen';body.replaceChildren(labeled('Vorhandene Variable',existing),labeled('Neue Variable',name));$('#edit-apply').onclick=()=>{const value=(existing.value||name.value).trim();if(!value)return notice('Variablenname fehlt.',true);insertIntoField(input,'$$','$$',value);closeModal('edit-modal')};openModal('edit-modal')}
