function appendTokens(el,text,values,inputs=null,render=null){const src=String(text||''),rx=/(\$\$[\s\S]+?\$\$|\$§[\s\S]+?\$§)/g;let p=0,m;while((m=rx.exec(src))){el.append(document.createTextNode(src.slice(p,m.index)));const token=m[0];if(token.startsWith('$$')){const name=token.slice(2,-2).trim();el.append(renderVariableText(name,values))}else{const raw=token.slice(2,-2).trim(),parts=raw.split('|'),value=(parts.shift()||'').trim(),label=parts.join('|').trim();if(/^https?:\/\//i.test(value))el.append(node('a',{class:'customer-token customer-link',href:value,target:'_blank',rel:'noopener noreferrer'},label||value));else el.append(node('span',{class:'customer-token'},value))}p=rx.lastIndex}el.append(document.createTextNode(src.slice(p)))}
function appendInline(el,text,values,inputs=null,render=null){const rx=/(\*\*[^*]+\*\*|\*[^*]+\*|~~[^~]+~~|\^\^[^^]+\^\^)/g;let p=0,m;while((m=rx.exec(text))){appendTokens(el,text.slice(p,m.index),values,inputs,render);const token=m[0],tag=token.startsWith('**')?'strong':token.startsWith('~~')?'s':token.startsWith('^^')?'span':'em',cut=tag==='em'?1:2,n=node(tag,tag==='span'?{class:'red-text'}:{});appendTokens(n,token.slice(cut,-cut),values,inputs,render);el.append(n);p=rx.lastIndex}appendTokens(el,text.slice(p),values,inputs,render)}
function appendRich(el,text,values,inputs=null,render=null){const lines=String(text||'').split('\n');for(let i=0;i<lines.length;){if(/^\s*\|.*\|\s*$/.test(lines[i])&&i+1<lines.length&&/^\s*\|(?:\s*:?-+:?\s*\|)+\s*$/.test(lines[i+1])){const table=node('table',{class:'doc-table'}),headers=lines[i].trim().slice(1,-1).split('|').map(x=>x.trim()),thead=node('thead'),tr=node('tr');headers.forEach(h=>{const th=node('th');appendInline(th,h,values,inputs,render);tr.append(th)});thead.append(tr);table.append(thead);i+=2;const tbody=node('tbody');while(i<lines.length&&/^\s*\|.*\|\s*$/.test(lines[i])){const row=node('tr');lines[i].trim().slice(1,-1).split('|').forEach(c=>{const td=node('td');appendInline(td,c.trim(),values,inputs,render);row.append(td)});tbody.append(row);i++}table.append(tbody);el.append(table);continue}if(i)el.append(node('br'));appendInline(el,lines[i],values,inputs,render);i++}}
function stepVisible(step,values){const c=step.meta?.condition;if(!c||!c.operator||c.operator==='always')return true;const actual=String(values[c.variable]??''),wanted=String(c.value??'');if(c.operator==='equals')return actual===wanted;if(c.operator==='not-equals')return actual!==wanted;if(c.operator==='contains')return actual.includes(wanted);if(c.operator==='set')return actual.trim()!=='';if(c.operator==='not-set')return actual.trim()==='';const a=Number(actual),b=Number(wanted);if(!Number.isFinite(a)||!Number.isFinite(b))return false;if(c.operator==='less-than')return a<b;if(c.operator==='greater-than')return a>b;return true}
function setupView(){const values={},inputs=new Map();CURRENT.variables.forEach(v=>values[v.name]=v.type==='random'?Array.from({length:5},()=>String.fromCharCode(97+Math.floor(Math.random()*26))).join(''):v.prefill||'');const vars=$('#variables');CURRENT.variables.forEach(v=>{if(v.hidden)return;const row=node('div',{class:'variable-row'}),label=node('strong',{},v.name);let input;if(v.type==='select')input=select((v.values||[]).map(x=>replaceVars(x,values)),replaceVars(v.prefill,values));else input=node('input',{type:v.type==='number'?'number':'text',value:values[v.name],readonly:v.type==='random'});input.oninput=()=>{values[v.name]=input.value;updateRenderedVariables(v.name,input.value)};input.onchange=()=>{values[v.name]=input.value;render()};inputs.set(v.name,input);row.append(label,input);vars.append(row)});if(!CURRENT.variables.some(v=>!v.hidden))$('.sidebar').classList.add('hidden');function render(){const root=$('#view-steps');root.replaceChildren();CURRENT.steps.filter(s=>stepVisible(s,values)).forEach((s,i)=>{const card=node('section',{class:'ticket'}),head=node('h2',{},(i+1)+'. '+(LABELS[s.action]||'Schritt')),body=node('div',{class:'ticket-body'});if(s.action==='external-task'){if(s.meta.system||s.meta.url){const r=node('div',{class:'kv'});r.append(node('strong',{},'System'),s.meta.url?node('a',{href:s.meta.url,target:'_blank',rel:'noopener noreferrer'},s.meta.system||s.meta.url):node('span',{},s.meta.system));body.append(r)}if(s.meta.tasks?.length){const ol=node('ol');s.meta.tasks.forEach(t=>{const li=node('li'),strong=node('strong',{},t.kind+' '),span=node('span');appendRich(span,externalTaskText(t),values,inputs,render);li.append(strong,span);ol.append(li)});body.append(ol)}}if(['phone-in','phone-out','email-in','email-out'].includes(s.action)&&s.meta.address){const r=node('div',{class:'kv'}),span=node('span');appendRich(span,s.meta.address,values,inputs,render);r.append(node('strong',{},s.action.endsWith('-in')?'Von':'An'),span);body.append(r)}s.fields.filter(f=>f.enabled).forEach(f=>{const r=node('div',{class:'kv'}),span=node('span');appendRich(span,f.value,values,inputs,render);r.append(node('strong',{},fieldDef(f.key).label),span);body.append(r)});if(s.subject){const block=node('div',{class:'text-block'}),content=node('div'),copy=node('button',{class:'copy'},'Kopieren');appendRich(content,s.subject,values,inputs,render);copy.onclick=()=>navigator.clipboard.writeText(replaceVars(s.subject,values));block.append(node('strong',{},s.action==='title-edit'?'Titel':s.action==='external-task'?'Ziel':'Betreff'),content,copy);body.append(block)}if(s.body){const block=node('div',{class:'text-block'}),content=node('div'),copy=node('button',{class:'copy'},'Kopieren');s.body.split('\n').forEach((line,j)=>{if(j)content.append(node('br'));appendRich(content,line,values,inputs,render)});copy.onclick=()=>navigator.clipboard.writeText(replaceVars(s.body,values));block.append(node('strong',{},'Text'),content,copy);body.append(block)}s.links.filter(l=>l.target.trim()).forEach(l=>{const r=node('div',{class:'kv'}),span=node('span');appendRich(span,l.target,values,inputs,render);r.append(node('strong',{},l.type||'Verknüpfung'),span);body.append(r)});card.append(head,body);root.append(card)})}render();const yaml=$('#yaml-actions');const down=node('button',{},'↓ YAML'),upLabel=node('label',{class:'button'},'↑ YAML'),up=node('input',{type:'file',accept:'.yaml,.yml'});up.classList.add('hidden');upLabel.append(up);down.onclick=()=>{const lines=['version: 1','values:',...CURRENT.variables.map(v=>'  '+JSON.stringify(v.name)+': '+JSON.stringify(values[v.name]??''))],blob=new Blob([lines.join('\n')+'\n'],{type:'application/yaml'}),url=URL.createObjectURL(blob),a=node('a',{href:url,download:(replaceVars(CURRENT.yamlName||CURRENT.name,values).replace(/[^A-Za-z0-9ÄÖÜäöüß._-]+/g,'-')||'werte')+'.yaml'});document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url)};up.onchange=async()=>{const file=up.files?.[0];if(!file)return;try{const text=await file.text(),start=text.split(/\r?\n/).findIndex(x=>x.trim()==='values:');if(start<0)throw new Error('values fehlt.');text.split(/\r?\n/).slice(start+1).forEach(line=>{const m=line.match(/^\s{2}("(?:\\.|[^"])*"):\s*("(?:\\.|[^"])*")\s*$/);if(!m)return;const name=JSON.parse(m[1]),value=JSON.parse(m[2]);if(Object.prototype.hasOwnProperty.call(values,name)){values[name]=value;const input=inputs.get(name);if(input)input.value=value;updateRenderedVariables(name,value)}});render();notice('YAML-Werte geladen.')}catch(e){notice(e.message||'YAML konnte nicht gelesen werden.',true)}finally{up.value=''}};yaml.append(down,upLabel)}
if(PAGE==='edit')setupEditor();if(PAGE==='config')setupConfig();if(PAGE==='admin')setupAdmin();if(PAGE==='view'&&CURRENT)setupView();
</script></body></html>
